# -*- coding: utf-8 -*-
# 批注数据：src/utils/attachments.ts（3997 行）
# 附件系统总装：40 余种 Attachment 类型的生产、节流与消息化

ANNOTATIONS = [
    (1, 'after', '''文件级总览：这是附件（attachment）系统的总装车间。附件是插在对话里的结构化旁路信息——@提及的文件、IDE 选区、todo 提醒、计划模式提示、技能清单、队友邮箱……它们不走模型输出，而是在每个用户回合由 getAttachments 并行生产、塞进 transcript。本文件定义全部类型与每个类型的生产函数。'''),
    (254, 'before', '''以下三个常量是提醒类附件的节流参数：todo 提醒 10 回合没写就催、催过 10 回合内不重复催；plan 与 auto 模式的全量提醒每 5 次一次。'''),
    (267, 'after', '''三组配置并列定义，plan_mode 与 auto_mode 用同一套节奏（5 回合间隔、每 5 次一次全量），代码也刻意镜像——两套模式的提醒逻辑是同构的。'''),
    (277, 'after', '''MAX_MEMORY_BYTES 的由来：光限 200 行不够（200 乘 500 字符可达 100KB），surfacer 每回合最多注入 5 个文件且绕过 per-message 预算，所以按字节截断（5 乘 4KB 等于 20KB 每回合）。截断反而保住了最相关内容——frontmatter 加开头通常是精华。'''),
    (289, 'after', '''MAX_SESSION_BYTES 累计上限 60KB：单回合有上限但长会话累计可观（生产环境观测到每会话约 26K token），预算约够 3 次完整注入；用完后停止预取。扫描消息而非在 context 里记数，意味着 compact 天然重置计数——旧附件没了，重新浮现是合法的。'''),
    (293, 'after', '''VERIFY_PLAN_REMINDER_CONFIG：计划验证提醒每 10 个人类回合一次。'''),
    (305, 'after', '''FileAttachment：@提及文件被完整读入的形态，content 直接是 FileReadTool 的输出，truncated 标记是否因大小截断。'''),
    (312, 'after', '''CompactFileReferenceAttachment：压缩后的大文件只留个路径引用，不内联内容——模型要用时再读。'''),
    (321, 'after', '''PDFReferenceAttachment：大 PDF（超过内联阈值页数）降级为轻量引用，只带页数与文件大小。'''),
    (333, 'after', '''AlreadyReadFileAttachment：文件已在上下文且未修改时返回这个类型，告诉系统不必重复发给 API——省 token 的关键去重形态。'''),
    (338, 'after', '''AgentMentionAttachment：@agent-xxx 提及子代理，只记 agentType。'''),
    (350, 'after', '''AsyncHookResponseAttachment：异步 hook 跑完后回填的结果，带进程号、hook 名、事件名与完整输出——异步协议的投递载体。'''),
    (380, 'after', '''HookAttachment 联合体：hook 系统的八种结果形态——取消、阻塞错误、非阻塞错误、执行中出错、截停续写、成功、附加上下文、系统消息、权限决定。hook 的每条出路都对应一种附件。'''),
    (438, 'after', '''HookNonBlockingErrorAttachment：hook 退出码非 0 但不阻塞流程，错误内容作为附件展示给模型。'''),
    (440, 'before', '''Attachment 主联合体：约 40 种形态的大一统类型。每个成员对应一类上下文注入场景；下面逐段看重点成员。'''),
    (717, 'after', '''联合体结尾是 bagel_console（内部诊断）与 companion_intro（伴侣彩蛋）。整个类型清单本身就是 CC 功能面的地图：每加一个功能，这里就多一种附件。'''),
    (728, 'after', '''TeammateMailboxAttachment：swarm 队友间传递的消息批，带来源、时间戳与可选颜色。'''),
    (737, 'after', '''TeamContextAttachment：队友首次回合收到的团队上下文——自己的 ID、队名、配置路径、任务列表路径。'''),
    (743, 'before', '''getAttachments：附件总入口。原文自嘲 this is janky——附件在提交时才算（拖慢提交），TODO 是改成边打字边算。'''),
    (761, 'after', '''极简模式闸门：CLAUDE_CODE_DISABLE_ATTACHMENTS 或 SIMPLE 时只返回排队命令附件。注释点出陷阱：query.ts 的 removeFromQueue 在附件消息跑完后无条件出队，这里返回空数组等于静默丢弃——所以不能返回空，至少要保住 task-notification（--bare 模式的 Coworker 靠它收通知）。'''),
    (768, 'after', '''整体 1 秒硬超时：createAbortController 加 setTimeout 一到就 abort。附件是提交路径上的开销，绝不能拖死主流程。'''),
    (815, 'after', '''userInputAttachments：仅在用户回合产出的附件——@提及文件、MCP 资源、agent 提及、回合 0 的技能发现（feature 门控做 DCE，外部构建里连 skill_discovery 字符串都不留；skipSkillDiscovery 挡住 SKILL.md 展开，否则 110KB 的技能文每调用触发约 3.3 秒分块查询）。'''),
    (819, 'after', '''先等用户输入类附件全部完成——包括把 @文件 塞进 nestedMemoryAttachmentTriggers，后续的 nested_memory 生产函数依赖这个集合已填充。顺序即正确性。'''),
    (941, 'after', '''allThreadAttachments：子代理也可用的线程安全附件——排队命令、日期变更、ultrathink、工具/代理/MCP 指令增量（全部为省 prompt cache 而做的 delta 化）、变更文件、嵌套记忆、技能清单、模式提醒、队友邮箱等。session_memory fork 专用跳过队友邮箱：它共享 leader 的 teamContext，会把 leader 的私信当成临时附件偷走。'''),
    (987, 'after', '''mainThreadAttachments：仅主线程的附件——IDE 选区与打开文件、输出风格、诊断（MCP 与 LSP 两路）、统一任务、异步 hook 响应、token 用量、预算、验证计划提醒。要么非并发安全，要么只对主对话有意义。'''),
    (994, 'after', '''线程附件与主线程附件并行求值——两组之间无依赖。'''),
    (1003, 'after', '''汇总返回：三层结果展平后滤掉 undefined 与 null。防御性过滤的理由：某个 getter 漏出 undefined 会让下面按 type 映射的代码直接崩。'''),
    (1042, 'after', '''maybe 包装器：每个附件生产器都套这层——计时、5 百分之采样上报耗时与体积、出错时记日志（Ant 用户额外全量记错）并返回空数组。单类附件失败绝不拖垮整轮。'''),
    (1044, 'after', '''INLINE_NOTIFICATION_MODES：prompt 与 task-notification 两种排队模式算「内联通知」。'''),
    (1083, 'after', '''getQueuedCommandAttachments：把队列里的 prompt 与 task-notification 都转成附件。注释解释为什么必须收 task-notification：主动代理循环里 useQueueProcessor 在查询期间跑不了，这些命令会永久滞留队列，hasPendingNotifications 恒真，Sleep 就会 0ms 醒来死循环。'''),
    (1101, 'after', '''getAgentPendingMessageAttachments：抽干子代理的待处理消息，统一包装成 queued_command 附件，origin 标 coordinator 且 isMeta 为真。'''),
    (1129, 'after', '''buildImageContentBlocks：粘贴的图片内容转 base64 image block，逐个过 maybeResizeAndDownsampleImageBlock 缩图降采样。'''),
    (1131, 'before', '''getPlanModeAttachmentTurnCount：倒着扫消息数「距上次 plan 提醒过了几回合」。关键细节在注释：必须数人类回合（非 meta、非 tool_result 的 user 消息）而非 assistant 消息——工具循环每轮都调附件生成，数 assistant 会把 5 回合间隔退化成每 5 次工具调用催一次。'''),
    (1163, 'after', '''返回计数与是否找到过提醒附件：没找到过就不节流（plan 模式第一回合必发）。'''),
    (1184, 'after', '''countPlanModeAttachmentsSinceLastExit：从尾部数到最近一次 plan_mode_exit 为止的 plan 附件个数——重进计划模式后 full 与 sparse 的循环从头计。'''),
    (1186, 'before', '''getPlanModeAttachments：plan 模式提醒的生产器。'''),
    (1219, 'after', '''重进检测：本会话曾退出过 plan 模式且计划文件存在时，发 plan_mode_reentry（一次性引导），随后清标志。'''),
    (1230, 'after', '''full 或 sparse 的判定：自上次 exit 起第 1、6、11……次发全量提醒，其余发稀疏版——常驻上下文成本与信息完整度的折中。'''),
    (1242, 'after', '''plan_mode 附件主体：带 full 或 sparse、是否子代理、计划文件路径与是否存在。'''),
    (1248, 'before', '''getPlanModeExitAttachment：刚退出 plan 模式时的一次性通知。若模式又是 plan（说明误触发）则清标志直接走。'''),
    (1273, 'after', '''原文注释顺带说明：退出 plan 不触发技能发现——等计划写完太迟了，该在「计划怎么部署」那句用户消息时就触发。'''),
    (1275, 'before', '''getAutoModeAttachmentTurnCount：与 plan 版同构的回合计数，多一个 auto_mode_exit 也终止计数的分支（exit 重置节流）。注释里的教训更狠：数 assistant 消息时单个人类回合带 100 次工具调用会发约 20 条提醒，auto 模式主打长 agent 会话，累计每会话多发 60 到 105 倍。'''),
    (1313, 'after', '''返回结构与 plan 版一致。'''),
    (1333, 'after', '''countAutoModeAttachmentsSinceLastExit：同样从尾部数到最近一次 exit。'''),
    (1344, 'after', '''两种活跃态都算：mode 直接是 auto，或 mode 是 plan 但转录分类器判定 auto 活跃（plan 带自动执行）。'''),
    (1374, 'after', '''getAutoModeAttachments 主体：同样有首回合必发与 full 或 sparse 周期。'''),
    (1400, 'after', '''getAutoModeExitAttachment：刚退出 auto 时发一次性通知；若 auto 仍活跃（含 plan 带自动）则抑制。'''),
    (1415, 'before', '''getDateChangeAttachments：跨午夜检测。设计要点在注释——date_change 附件追加在对话尾部，模型学到新日期却不动缓存前缀；头部消息里的旧日期刻意不清，清了会让整个会话下一回合全变 cache_creation（通宵会话跨午夜一次约 92 万有效 token）。'''),
    (1425, 'after', '''第一回合只记录日期不发附件。'''),
    (1444, 'after', '''日期变更时顺手把昨天的转录按天落盘（Kairos 助手模式，供凌晨 1 到 5 点的 dream 技能找素材），fire-and-forget；然后发 date_change 附件。'''),
    (1452, 'after', '''getUltrathinkEffortAttachment：用户输入含 ultrathink 关键词且功能开启时，发 high 推理力度附件并埋点。'''),
    (1455, 'before', '''getDeferredToolsDeltaAttachment：延迟工具的增量化通告。导出给 compact.ts 复用——两处闸门必须一致。'''),
    (1471, 'after', '''三道闸门镜像 isToolSearchEnabled 的同步部分：附件文案说「可用 ToolSearch 拿到」，请求里就必须真有 ToolSearch，否则文案撒谎。异步阈值检查不复刻（会重复上报决策埋点）。'''),
    (1475, 'after', '''算出工具增量后发 deferred_tools_delta 附件：新增名字与行、移除名字。'''),
    (1490, 'before', '''getAgentListingDeltaAttachment：把代理清单从 AgentTool 的 description 挪进增量附件。动机是 cache：清单嵌在描述里时，MCP 异步连接、插件重载、权限模式变化都会改描述，进而打爆整个工具 schema 缓存（观测到机群 10.2% 的 cache_creation 浪费）。'''),
    (1521, 'after', '''过滤逻辑镜像 AgentTool 的 prompt：MCP 依赖、deny 规则、allowedAgentTypes 白名单，三层过滤保持同步否则两处清单不一致。'''),
    (1530, 'after', '''从 transcript 里已有的增量附件重建「已通告集合」：加过 minus 移除过。'''),
    (1544, 'after', '''确定性排序：代理加载顺序不确定（插件加载竞态、MCP 异步连接），不排序会让同样的集合产出字节不同的附件，打爆缓存。'''),
    (1556, 'after', '''发增量：新增类型与行、移除类型，isInitial 标首次，showConcurrencyNote 按订阅档决定是否附「可并发开多个代理」的提示。'''),
    (1559, 'before', '''getMcpInstructionsDeltaAttachment：MCP 服务器指令的增量化。导出给 compact.ts 与 reactiveCompact.ts 作单一事实源。'''),
    (1585, 'after', '''chrome 的 ToolSearch 提示是客户端手写且依赖 ToolSearch 开启；真正的服务器 instructions 无条件。先把客户端侧合成条目算好，再进纯 diff。'''),
    (1595, 'after', '''getCriticalSystemReminderAttachment：透传 context 上的实验性关键系统提醒。'''),
    (1612, 'after', '''getOutputStyleAttachment：非默认输出风格时通告——默认风格不发（省 token）。'''),
    (1644, 'after', '''getSelectedLinesFromIDE：IDE 选区转附件，带起止行、文件路径与相对展示路径；先过读权限闸。'''),
    (1689, 'after', '''getDirectoriesToProcess：算出两层目录清单——nestedDirs（CWD 到目标文件，做完整 CLAUDE.md 加规则）与 cwdLevelDirs（根到 CWD，只做条件规则）。顺序都是父到子。'''),
    (1707, 'after', '''isInstructionsMemoryType：四个指令级类型（User、Project、Local、Managed）才触发 InstructionsLoaded hook；条件规则不算。'''),
    (1710, 'before', '''memoryFilesToAttachments：把记忆文件转附件并去重、登记。'''),
    (1724, 'after', '''双重去重的原因：loadedNestedMemoryPaths 是不淘汰的 Set，而 readFileState 是 100 条的 LRU——忙会话里 LRU 条目被挤掉后，若只靠 readFileState 会每个淘汰周期重新注入同一份 CLAUDE.md。'''),
    (1750, 'after', '''登记 readFileState 时的细节：注入内容与磁盘不一致（剥过 HTML 注释、frontmatter 或截断过的 MEMORY.md）时，缓存原始磁盘字节并标 isPartialView——Edit 与 Write 见到标志会要求先真正 Read；变更检测仍按真实内容走。'''),
    (1775, 'after', '''循环结束返回全部新附件；hook 是 fire-and-forget 的审计钩子（InstructionsLoaded），带加载原因——glob 命中、include 还是嵌套遍历。'''),
    (1792, 'before', '''getNestedMemoryAttachmentsForFile：对单个文件路径做嵌套记忆遍历。顺序敏感，注释列死四阶段。'''),
    (1815, 'after', '''阶段 1：Managed 与 User 层的条件规则优先。'''),
    (1856, 'after', '''阶段 4：根到 CWD 的每层目录只处理条件规则（无条件规则启动时就急切加载过了）；tengu_paper_halyard 开关可整体跳过 Project 与 Local 层。'''),
    (1862, 'after', '''异常只记日志返回已收集的部分——嵌套记忆加载失败不该影响回合。'''),
    (1892, 'after', '''getOpenedFileFromIDE：先塞嵌套记忆附件，再跟打开文件附件——顺序保证 CLAUDE.md 语境先到。'''),
    (1894, 'before', '''processAtMentionedFiles：@提及文件的核心处理。支持行范围语法（file.txt#L10-20）、目录自动展开、大小与权限校验。'''),
    (1945, 'after', '''目录分支：列出条目名，超过 1000 条截断并附省略提示，产出 directory 附件；stat 失败则落到文件逻辑继续。'''),
    (1963, 'after', '''并行读完所有提及文件，filter(Boolean) 滤掉被拒或失败的。'''),
    (1993, 'after', '''processAgentMentions：agent- 前缀剥掉后找定义，找不到记埋点返回 null。'''),
    (2008, 'after', '''MCP 资源提及格式是 @server:uri；URI 本身可能含冒号，所以 split 后要重新 join。'''),
    (2061, 'after', '''processMcpResourceAttachments：找到已连接客户端与资源元数据后 readResource，产出 mcp_resource 附件；四类失败都只记埋点。'''),
    (2063, 'before', '''getChangedFiles：监工 readFileState 里登记过的文件，改了就生成差异片段附件——模型离开后文件被外部改动的回传通道。'''),
    (2078, 'after', '''带 offset 或 limit 的部分读跳过——TODO：还没有部分读的变更对比支持。'''),
    (2115, 'after', '''差异为空说明文件被 touch 过但内容没变——不算变更。'''),
    (2155, 'after', '''只有 ENOENT（文件真没了）才从 readFileState 逐出；瞬时 stat 失败（编辑器原子写的 tmp 加 rename 间隙、权限抖动、网络盘打嗝）绝不逐出，否则下一次 Edit 误报 code-6。VS Code 的自动保存与保存时格式化特别容易踩这个竞态（PR #18525 回归分析）。'''),
    (2161, 'after', '''汇总非空结果返回。'''),
    (2194, 'after', '''getNestedMemoryAttachments：遍历触发集逐文件生成，最后清空触发集。先查触发集再取 AppState——getAppState 要等一次 React 渲染周期，而空触发集是常态。'''),
    (2196, 'before', '''getRelevantMemoryAttachments：自动记忆的相关性检索与注入。'''),
    (2213, 'after', '''@提及了某个代理就只搜它的记忆目录（隔离）；否则搜自动记忆目录。'''),
    (2234, 'after', '''已读文件与已浮现过的都滤掉，最多取 5 条；alreadySurfaced 在选择器内部已滤过，这里再滤是双保险（多目录结果可能重新引入别处滤过的路径）。'''),
    (2242, 'after', '''读入选中记忆，产出 relevant_memories 附件。'''),
    (2266, 'after', '''collectSurfacedMemories：扫历史消息收集已浮现的路径集合与累计字节。又是扫描而非记状态——compact 后自然重置。'''),
    (2279, 'before', '''readMemoriesForSurfacing：按行与字节双重截断读记忆文件；截断时附加截断说明并指引用 FileRead 工具看全文——选择器既然挑了它，frontmatter 加开头也值得给。'''),
    (2321, 'after', '''失败的文件直接丢弃，不阻断其他记忆注入。'''),
    (2332, 'after', '''memoryHeader：年龄加路径的头部串。导出给 messages.ts——resume 的老会话没有存 header 时兜底重算。'''),
    (2353, 'after', '''MemoryPrefetch：记忆检索的预取句柄。promise 在用户回合开始时启动，模型流式输出与工具执行期间后台跑；收集点看 settledAt 决定取用或下轮再试，永不阻塞回合。'''),
    (2361, 'before', '''startRelevantMemoryPrefetch：回合起点启动预取。'''),
    (2382, 'after', '''单词输入（无空白）上下文太少，不值得跑检索——直接跳过。'''),
    (2386, 'after', '''会话累计字节超上限也跳过——预算烧完停止预取。'''),
    (2390, 'after', '''子 AbortController 挂在回合级 controller 下：用户按 Escape 立即取消侧查询，而不是等 queryLoop 退出才触发 dispose。'''),
    (2424, 'after', '''句柄的 dispose 会在所有生成器退出路径上触发（query.ts 用 using 绑定）：abort 加埋点（是否首迭代就被藏、消耗在第几迭代、延迟多少毫秒）——不用在主循环里约 13 个 return 点逐一埋点。'''),
    (2449, 'after', '''hasToolResultContent：检查 user 消息里有没有 tool_result 块。比查 toolUseResult 更可靠——子代理的结果消息会显式把它设成 undefined。'''),
    (2503, 'after', '''collectRecentSuccessfulTools：上个真人回合以来成功且从未报错的工具清单。任何一次报错或结果未知都排除——模型正在挣扎的工具，参考文档要留着；一路成功的工具，再给它推文档是噪音。倒序扫时 tool_use 在 assistant 内容、tool_result 在 user 内容，先按 id 收集最后统一归并。'''),
    (2520, 'before', '''filterDuplicateMemoryAttachments：预取记忆注入前的最后去重——排除模型已通过读写工具或先前回合拿到过的路径。'''),
    (2541, 'after', '''注释强调顺序是命门：早先把 readFileState 写入放在预取阶段，过滤时看到的全是「已在上下文」——自引用过滤把候选全杀光。写入推迟到过滤之后才打破循环。'''),
    (2601, 'after', '''getDynamicSkillAttachments：文件操作中撞见的技能目录，转成 dynamic_skill 附件；readdir 与逐目录 stat SKILL.md 全并行。'''),
    (2607, 'after', '''sentSkillNames 按 agentId 记账（空串即主线程）——不按代理隔离的话，主线程填满集合会让每个子代理的去重结果为空，子代理永远看不到技能清单。'''),
    (2615, 'after', '''resetSentSkillNames：技能集真变了（插件重载、技能文件变更）时清账让新技能重新通告；compact 不清——压缩后重注入每次约 4K token，收益太小。'''),
    (2636, 'after', '''suppressNext 标志：resume 时转录里已有技能清单，本进程不再重发。'''),
    (2641, 'after', '''FILTERED_LISTING_MAX 等于 30：过滤后清单超 30 个就退回只列内置，保住典型用户回合 0 有清单的保证，同时防 MCP 重度用户（100 多个服务器）被截断。'''),
    (2659, 'after', '''filterToBundledAndMcp：只留内置加 MCP 技能；两者合计超限再退到纯内置。长尾（用户、项目、插件技能，200 多个）走发现通道。'''),
    (2661, 'before', '''getSkillListingAttachments：技能清单附件的生产器。'''),
    (2715, 'after', '''resume 路径：把当前全部技能标记为已发送——上个进程已经注入过清单，之后只有真正的增量（比如重载插件）才通告。代价是跨进程新增的技能要等下个非 resume 会话才被通告，可接受。'''),
    (2725, 'after', '''isInitial：一条都没发过即首轮全量清单。'''),
    (2751, 'after', '''最终按上下文窗口预算格式化清单内容，发 skill_listing 附件。原 getSkillDiscoveryAttachment 已挪去 skillSearch 的 prefetch 模块——为的是把 skill_discovery 字符串字面量关进 feature 门控模块，不泄漏进外部构建。'''),
    (2790, 'after', '''extractAtMentionedFiles：两套正则并行——带引号路径（支持空格）与普通路径；先抽引号形式并跳过 agent 提及（以 (agent) 结尾），普通形式里以引号开头的也已处理过，最后去重。'''),
    (2800, 'after', '''extractMcpResourceMentions：@server:uri 形式的资源提及。'''),
    (2828, 'after', '''extractAgentMentions：两种格式——@agent-xxx 手打与自动补全的引号格式；字符类放行冒号、点、@ 以支持插件作用域代理。'''),
    (2852, 'after', '''parseAtMentionedFileLines：解析 file.txt#L10-20；#锚点 形式剥掉；#L10 等价 #L10-10。'''),
    (2877, 'after', '''getDiagnosticAttachments：IDE 诊断附件——但只有模型有 Bash 工具时才有意义（没有 Bash 就无法行动）。'''),
    (2935, 'after', '''getLSPDiagnosticAttachments：被动 LSP 服务器的诊断投递，仿异步 hook 注册表模式；取走即清注册表防泄漏，出错返回空数组让其他附件继续。'''),
    (2937, 'before', '''getAttachmentMessages：对外主接口——异步生成器逐个 yield 附件消息。query.ts 的工具循环每轮调用它。'''),
    (2970, 'after', '''逐个 createAttachmentMessage（随机 UUID 加时间戳）产出。'''),
    (2986, 'before', '''tryGetPDFReference：大 PDF 降级判定——超过内联阈值页数就只给引用。页数拿不到时按每页约 100KB 的体积启发式估。'''),
    (2999, 'after', '''effectivePageCount：pdfinfo 有就用真页数，否则体积启发式。'''),
    (3018, 'after', '''任何 stat 失败都返回 null 走正常读取路径——降级判定绝不能挡住正常流程。'''),
    (3020, 'before', '''generateFileAttachment：@提及与压缩恢复共用的核心文件读取逻辑。'''),
    (3043, 'after', '''第一道闸：deny 规则直接拒绝。'''),
    (3066, 'after', '''@提及模式下超大小上限的非 PDF 文件直接放弃（PDF 有自己的页数处理）。'''),
    (3074, 'after', '''大 PDF 换轻量引用，不内联。'''),
    (3119, 'after', '''already_read_file 优化：时间戳一致才走。注释详述坑——FileReadTool 存的是 Date.now()，Edit 与 Write 存的是文件 mtime，前者大于后者时无法可靠比较，只有后者路径才敢用该优化。'''),
    (3140, 'after', '''compact 模式下超大文件只留 compact_file_reference 引用。'''),
    (3199, 'after', '''超 token 或超大异常时退到截断读（只读前 MAX_LINES_TO_READ 行）；其他异常向上抛。'''),
    (3210, 'after', '''createAttachmentMessage：附件包成消息——随机 UUID 加 ISO 时间戳。'''),
    (3264, 'after', '''getTodoReminderTurnCounts：倒序扫出距上次 TodoWrite 与上次提醒各多少 assistant 回合；思考消息跳过；TodoWrite 的判定在计数前做——写入那条自身不算「过了 1 回合」。'''),
    (3317, 'after', '''getTodoReminderAttachments：超过 10 回合没写 todo 且距上次提醒超 10 回合才催；有 Brief 工具（SendUserMessage）时整个不催——主沟通通道换成简报后 todo 是旁路，催它反而和简报工作流打架。'''),
    (3373, 'after', '''getTaskReminderTurnCounts：任务版回合计数，判定对象是 TaskCreate 或 TaskUpdate。'''),
    (3432, 'after', '''getTaskReminderAttachments：todo v2 启用后的任务提醒；ant 用户跳过；同样被 Brief 工具抑制。'''),
    (3439, 'before', '''getUnifiedTaskAttachments：统一任务框架的附件——替代了旧的后台 shell、远程会话、异步代理三个独立函数。'''),
    (3462, 'after', '''生成附件同时把偏移与逐出回写到 AppState，下轮只报增量。'''),
    (3518, 'after', '''getAsyncHookResponseAttachments：从注册表取走已完成的异步 hook 响应，转附件后立即从注册表移除防重复处理——与 LSP 诊断同款「取走即清」模式。'''),
    (3532, 'before', '''getTeammateMailboxAttachments：swarm 队友邮箱。注释明确：队友是并行独立会话，不是父子子代理。'''),
    (3610, 'after', '''两个消息源：文件邮箱（轮询间隙到达的）与 AppState.inbox（回合中被 useInboxPoller 入队的）。看队友转录或自己是进程内队友时跳过 inbox——进程内队友与 leader 共享 AppState，那里面是 leader 的私信，读了就泄漏（包括广播的自回声）。'''),
    (3642, 'after', '''两源合并带去重：同一消息可能既在文件邮箱又被 poller 抄进 inbox（竞态），按来源加时间戳加正文前 100 字符做键。'''),
    (3665, 'after', '''同一代理的多条 idle 通知折叠成最新一条——一遍解析一遍过滤，不重复解析。'''),
    (3696, 'after', '''附件先构建、消息后标记已读——顺序防丢失。结构化协议消息（权限请求、关闭审批）刻意保持未读，留给 useInboxPoller 路由到专用处理器；若附件抢先标读，协议消息会被当成裸文本塞给模型。'''),
    (3752, 'after', '''team lead 处理 shutdown_approved：从团队文件移除成员、退掉其任务、并从 AppState 的 teamContext 删掉。-p 模式下 useInboxPoller 不跑，只能在这里做。'''),
    (3766, 'after', '''inbox 消息最后才标 processed——同样是为了前面任何一步失败都不丢消息。'''),
    (3769, 'after', '''返回构建好的队友邮箱附件。'''),
    (3805, 'after', '''getTeamContextAttachment：只给队友发、只在首回合发（还没有 assistant 消息即首回合）。'''),
    (3826, 'after', '''getTokenUsageAttachment：环境变量显式开启才发 token 用量附件。'''),
    (3844, 'after', '''getOutputTokenUsageAttachment：TOKEN_BUDGET 特性下的回合与会话输出 token 计量。'''),
    (3862, 'after', '''getMaxBudgetUsdAttachment：设了美元预算才发用量——用掉、总额、剩余。'''),
    (3889, 'after', '''getVerifyPlanReminderTurnCount：数计划退出后的人类回合；tool_result 也是无 meta 的 user 消息，必须按 toolUseResult 滤掉，否则 10 回合间隔退化成每 10 次工具调用。'''),
    (3929, 'after', '''getVerifyPlanReminderAttachment：计划验证未开始也未完成时，每逢 10 的倍数回合提醒一次。'''),
    (3955, 'after', '''getCompactionReminderAttachment：超长上下文（百万级窗口）且用量过四分之一时提醒该压缩了——给模型一个主动减负的信号。'''),
    (3983, 'after', '''getContextEfficiencyAttachment：无 snip 的上下文增长到阈值后的效率提示；节流全在 shouldNudgeForSnips——间隔会因已有提示、snip 标记与压缩边界重置。'''),
    (3997, 'after', '''isFileReadDenied：读权限 deny 规则的统一判定，全文件所有文件类附件共用的守门人。'''),
]
